window.docContents[206].resolve({"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation___-Finally--Assignment-Preserves-Store-Typing":{"contents":"Next, we must show that replacing the contents of a cell in the\nstore with a new value of appropriate type does not change the\noverall type of the store.  (This is needed for the assign\nrule.)\n\ntheorem assign_pres_store_typing {δ : StoreTy} {ρ : Store} {l : Nat} {t : Tm}\n  (hLen : l < ρ.length)\n  (hStoreTy : δ ⊢ ρ)\n  (hTy : <{ ∅ / δ ⊢ t ⦂ ~(δ[l]) }>) :\n  δ ⊢ ρ.set l t := by\n    have ⟨h₁, h₂⟩ := hStoreTy\n    constructor\n    · simp_all [List.length_set]\n    · intro l' hLen'\n      by_cases h₁ : l' = l\n      · subst_vars\n        rw [Store_get_set_eq] <;> assumption\n      · rw [Store_get_set_neq] <;> try assumption\n        apply h₂\n        simp_all [List.length_set]\n\n\n","context":"Type Systems\u0009References: Typing Mutable References\u0009Properties\u0009Preservation, Finally","header":"9.5.3.2. Assignment Preserves Store Typing","id":"/References/#Type-Systems--References___-Typing-Mutable-References--Properties--Preservation___-Finally--Assignment-Preserves-Store-Typing"}});